class Solution:
    def canReach(self, s: str, minJump: int, maxJump: int) -> bool:
        n = len(s)
        if s[-1] == '1':
            return False
        reachable = [False] * n
        reachable[0] = True
        count = 0
        for i in range(1, n):
            if i >= minJump:
                count += reachable[i - minJump]
            if i > maxJump:
                count -= reachable[i - maxJump - 1]
            reachable[i] = count > 0 and s[i] == '0'
        return reachable[-1]

